/bin/bash -lc "python3 -c 'import subprocess, pathlib; retired=[\"python/legacy_review_shell/aggregate-findings.sh\",\"python/legacy_review_shell/aggregate-findings-phrases.inc.bash\",\"python/legacy_review_shell/compose-review-findings.sh\",\"python/legacy_review_shell/tally-code-votes.sh\",\"python/legacy_review_shell/emit-tally.sh\",\"python/legacy_review_shell/log-phase.sh\",\"skills/review/scripts/prune-nit-findings.sh\",\"skills/review/scripts/prune-nit-findings.md\",\"skills/review/scripts/test-prune-nit-findings.sh\",\"skills/review/scripts/test-prune-nit-findings.md\"]; r=subprocess.run([\"git\",\"ls-files\",\"-z\",\"--\",\".\",\":(exclude)larch-logs/**\"],capture_output=True,text=True); print(r.stderr,end=\"\");
for p in [x for x in r.stdout.split(\"\\0\") if x]:
    path=pathlib.Path(p)
    try: text=path.read_text(encoding=\"utf-8\", errors=\"replace\")
    except Exception: continue
    for i,line in enumerate(text.splitlines(),1):
        for rr in retired:
            if rr in line: print(f\"{p}:{i}: {rr}\")'"

